        getPerformanceSummary(history) {
            if (!history.length) return {};

            var last = history[history.length - 1];
            var r = last.results || {};
            var finalInflation = (r.inflation != null) ? r.inflation : 82;
            var finalGDP = (r.gdpGrowth != null) ? r.gdpGrowth : 0.8;
            var finalUnemployment = (r.unemployment != null) ? r.unemployment : 11.4;
            var finalReserves = (r.reserves != null) ? r.reserves : 2.8;
            var finalFiscal = (r.fiscalBalance != null) ? r.fiscalBalance : -2.1;

            var inflScore = Math.max(0, Math.min(100, (82 - finalInflation) / (82 - 35) * 100));
            var gdpScore = Math.max(0, Math.min(100, (finalGDP - 0.8) / (2.5 - 0.8) * 100));
            var unempScore = Math.max(0, Math.min(100, (11.4 - finalUnemployment) / (11.4 - 9) * 100));
            var fiscalScore = Math.max(0, Math.min(100, (finalFiscal + 2.1) / (0 + 2.1) * 100));
            var reserveScore = Math.max(0, Math.min(100, (finalReserves - 2.8) / (5 - 2.8) * 100));

            var totalScore = Math.round(
                inflScore * 0.30 +
                gdpScore * 0.25 +
                unempScore * 0.20 +
                fiscalScore * 0.15 +
                reserveScore * 0.10
            );

            var _t = function(k){ try { return window.mySimulation.t(k); } catch(e){ return k; } };
            var performance = _t('perf_crisis');
            if (totalScore > 70) performance = _t('perf_excellent');
            else if (totalScore > 50) performance = _t('perf_competent');
            else if (totalScore > 30) performance = _t('perf_struggling');

            var insights = [];
            if (finalInflation <= 35) {
                insights.push(_t('insight_infl_success'));
            } else if (finalInflation <= 55) {
                insights.push(_t('insight_infl_partial'));
            } else {
                insights.push(_t('insight_infl_high'));
            }

            if (finalGDP >= 2.5) {
                insights.push(_t('insight_gdp_strong'));
            } else if (finalGDP < 0) {
                insights.push(_t('insight_gdp_recession'));
            }

            if (finalReserves >= 5) {
                insights.push(_t('insight_reserves_strong'));
            } else if (finalReserves < 2) {
                insights.push(_t('insight_reserves_low'));
            }

            return {
                totalScore: totalScore,
                inflationScore: Math.round(inflScore),
                gdpScore: Math.round(gdpScore),
                unemploymentScore: Math.round(unempScore),
                fiscalScore: Math.round(fiscalScore),
                reserveScore: Math.round(reserveScore),
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.taylorGap < -15) return window.mySimulation.t('hint_taylor_loose');
            if (results.inflation > state.domainState.inflation) return window.mySimulation.t('hint_inflation_rising');
            if (results.reserves < 2) return window.mySimulation.t('hint_reserves_critical');
            if (results.credibility < 20) return window.mySimulation.t('hint_credibility_low');
            if (results.gdpGrowth < -1) return window.mySimulation.t('hint_recession');
            if (results.inflation < 40 && results.gdpGrowth > 1.5) return window.mySimulation.t('hint_good_progress');
            return null;
        }

