        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            if (!briefEl) return;

            var lang = 'en';
            try {
                lang = (window.mySimulation && window.mySimulation.lang) ? window.mySimulation.lang : ((document.documentElement && document.documentElement.lang) || 'en');
            } catch(e) {}

            if (lang === 'es') {
                briefEl.innerHTML = '<strong>' + round.title_es + '</strong><br><br>' + round.desc_es;
            } else {
                briefEl.innerHTML = '<strong>' + round.title_en + '</strong><br><br>' + round.desc_en;
            }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new MacroAdapter(), {
            simulationType: 'macro_argentina_311',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

})();
